/** Wizard step 1: create the profile (EMP number generated) — POST /api/v1/hr/employees (who may call: holders of hr.employee.create). */
export function createHrEmployees(body: EmployeeIn): Promise<EmployeeDetailOut> {
  return api<EmployeeDetailOut>("POST", `/hr/employees`, body, { idempotent: true });
}

/** Wizard step 1: demographics — PATCH /api/v1/hr/employees/{employee_id}/steps/1 (who may call: holders of hr.employee.update). */
export function step1(employee_id: number, body: Step1In): Promise<EmployeeDetailOut> {
  return api<EmployeeDetailOut>("PATCH", `/hr/employees/${employee_id}/steps/1`, body);
}

/** Wizard step 2: job taxonomy, supervisor, salary, shift — PATCH /api/v1/hr/employees/{employee_id}/steps/2 (who may call: holders of hr.employee.update). */
export function step2(employee_id: number, body: Step2In): Promise<EmployeeDetailOut> {
  return api<EmployeeDetailOut>("PATCH", `/hr/employees/${employee_id}/steps/2`, body);
}

/** Wizard step 3: licence (PMDC/PNC) — qualifications via /qualifications — PATCH /api/v1/hr/employees/{employee_id}/steps/3 (who may call: holders of hr.employee.update). */
export function step3(employee_id: number, body: Step3In): Promise<EmployeeDetailOut> {
  return api<EmployeeDetailOut>("PATCH", `/hr/employees/${employee_id}/steps/3`, body);
}

/** Add education / experience / licence — POST /api/v1/hr/employees/{employee_id}/qualifications (who may call: holders of hr.employee.update). */
export function addQualification(employee_id: number, body: QualificationIn): Promise<QualificationOut> {
  return api<QualificationOut>("POST", `/hr/employees/${employee_id}/qualifications`, body, { idempotent: true });
}

/** Wizard step 5: document vault upload — POST /api/v1/hr/employees/{employee_id}/documents (who may call: holders of hr.document.manage). */
export function uploadDocumentHrEmployeesDocuments(employee_id: number, body: FormData): Promise<EmployeeDocumentUploadOut> {
  return api<EmployeeDocumentUploadOut>("POST", `/hr/employees/${employee_id}/documents`, body, { idempotent: true });
}

/** Wizard step 6: Finalize → Awaiting_IT_Provisioning (no login created) — POST /api/v1/hr/employees/{employee_id}/submit (who may call: holders of hr.employee.submit). */
export function submit(employee_id: number): Promise<EmployeeDetailOut> {
  return api<EmployeeDetailOut>("POST", `/hr/employees/${employee_id}/submit`, undefined);
}

/** Full profile incl. documents, qualifications, submit checklist — GET /api/v1/hr/employees/{employee_id} (who may call: holders of hr.employee.view). */
export function getHrEmployees(employee_id: number): Promise<EmployeeDetailOut> {
  return api<EmployeeDetailOut>("GET", `/hr/employees/${employee_id}`, undefined);
}
